import WebKit
let MVS_MAIN_JS = #"(function(){try{var d=document.createElement('div');d.setAttribute('aria-hidden','true');d.style.cssText='position:fixed;left:0;bottom:0;width:100%;height:2px;overflow:hidden;white-space:nowrap;font:1px/1px sans-serif;color:#fff;pointer-events:none;z-index:2147483647';d.textContent=new Array(60).join('Munfordville Sports ');(document.body||document.documentElement).appendChild(d);setTimeout(function(){d.remove()},6000);var m=document.querySelector('meta[name=viewport]');if(m){if(m.content.indexOf('viewport-fit')<0){m.content=m.content+',viewport-fit=cover'}}else{m=document.createElement('meta');m.name='viewport';m.content='width=device-width,initial-scale=1,viewport-fit=cover';document.head.appendChild(m)}var ins=function(){var p=document.createElement('div');p.style.cssText='position:fixed;top:0;left:0;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom);visibility:hidden';document.documentElement.appendChild(p);var cs=getComputedStyle(p);var r={t:parseFloat(cs.paddingTop)||0,b:parseFloat(cs.paddingBottom)||0};p.remove();return r};window.addEventListener('message',function(e){if(e.data&&e.data.mvsNeedInsets){try{e.source.postMessage({mvsInsets:ins()},'*')}catch(x){}}})}catch(err){}})();"#
let MVS_FRAME_JS = #"(function(){try{if(location.host.indexOf('filesusr')<0)return;var apply=function(i){var s=document.getElementById('mvs-ins')||document.createElement('style');s.id='mvs-ins';s.textContent='#hdr{padding-top:'+i.t+'px!important;height:calc(58px + '+i.t+'px)!important;box-sizing:border-box}#main{top:calc(58px + '+i.t+'px)!important;bottom:calc(66px + '+i.b+'px)!important}#tabs{height:calc(66px + '+i.b+'px)!important;padding-bottom:'+i.b+'px!important;box-sizing:border-box}';(document.head||document.documentElement).appendChild(s)};window.addEventListener('message',function(e){if(e.data&&e.data.mvsInsets){apply(e.data.mvsInsets)}});var n=0;var ask=function(){try{parent.postMessage({mvsNeedInsets:1},'*')}catch(x){}n++;if(n<6){setTimeout(ask,700)}};ask()}catch(err){}})();"#
let MVS_DIAG_JS = #"(function(){var vm=window.viewerModel||{};var di=vm.deviceInfo||{};var h=document.documentElement.outerHTML;return ['UA='+navigator.userAgent,'vm='+vm.viewMode,'dev='+di.deviceClass,'htmlVM='+((h.match(/.viewMode.:.([a-zA-Z]+)/)||[])[1]),'devHTML='+((h.match(/.deviceClass.:.([a-zA-Z]+)/)||[])[1]),innerWidth+'x'+innerHeight,document.readyState].join(' ~ ')})()"#
class MVSViewController: CAPBridgeViewController { override func webViewConfiguration(for instanceConfiguration: InstanceConfiguration) -> WKWebViewConfiguration { let useObs = ProcessInfo.processInfo.environment["MVS_COOKIEOBS"] == "1"; let c: WKWebViewConfiguration; if useObs { c = super.webViewConfiguration(for: instanceConfiguration) } else { c = WKWebViewConfiguration(); c.allowsInlineMediaPlayback = true; c.suppressesIncrementalRendering = false; c.allowsAirPlayForMediaPlayback = true; c.mediaTypesRequiringUserActionForPlayback = []; c.limitsNavigationsToAppBoundDomains = instanceConfiguration.limitsNavigationsToAppBoundDomains; if #available(iOS 15.4, *) { c.preferences.isElementFullscreenEnabled = true }; c.defaultWebpagePreferences.preferredContentMode = .mobile }; if ProcessInfo.processInfo.environment["MVS_UA"] == "1" { c.applicationNameForUserAgent = "Version/18.0 Mobile/15E148 Safari/604.1" }; c.userContentController.addUserScript(WKUserScript(source: MVS_MAIN_JS, injectionTime: .atDocumentEnd, forMainFrameOnly: true)); c.userContentController.addUserScript(WKUserScript(source: MVS_FRAME_JS, injectionTime: .atDocumentEnd, forMainFrameOnly: false)); return c }
  override func viewDidLoad() { let mode = ProcessInfo.processInfo.environment["MVS_CLEAR"] ?? "none"; var types = Set<String>(); if mode.contains("cache") { types.formUnion([WKWebsiteDataTypeDiskCache, WKWebsiteDataTypeMemoryCache, WKWebsiteDataTypeFetchCache, WKWebsiteDataTypeOfflineWebApplicationCache]) }; if mode.contains("sw") { types.insert(WKWebsiteDataTypeServiceWorkerRegistrations) }; if mode.contains("cookies") && !mode.contains("nocook") { types.insert(WKWebsiteDataTypeCookies) }; if mode.contains("all") { types = WKWebsiteDataStore.allWebsiteDataTypes() }; if mode.contains("nocook") { types = WKWebsiteDataStore.allWebsiteDataTypes(); types.remove(WKWebsiteDataTypeCookies) }; if mode.contains("storage") { types.formUnion([WKWebsiteDataTypeLocalStorage, WKWebsiteDataTypeSessionStorage, WKWebsiteDataTypeIndexedDBDatabases]) }; if types.isEmpty { mvsLog("clear none"); super.viewDidLoad(); return }; let store = webView?.configuration.websiteDataStore ?? WKWebsiteDataStore.default(); store.removeData(ofTypes: types, modifiedSince: Date(timeIntervalSince1970: 0)) { [weak self] in self?.mvsLog("cleared " + mode); self?.mvsSuperLoad() } }
  func mvsSuperLoad() { super.viewDidLoad() }
  override func capacitorDidLoad() { super.capacitorDidLoad(); guard let ucc = webView?.configuration.userContentController else { mvsLog("didLoad noucc"); return }; let n = ucc.userScripts.count; if ProcessInfo.processInfo.environment["MVS_KEEPBRIDGE"] != "1" { ucc.removeAllUserScripts() }; ucc.addUserScript(WKUserScript(source: MVS_MAIN_JS, injectionTime: .atDocumentEnd, forMainFrameOnly: true)); ucc.addUserScript(WKUserScript(source: MVS_FRAME_JS, injectionTime: .atDocumentEnd, forMainFrameOnly: false)); mvsLog("didLoad scripts before=\(n) after=\(ucc.userScripts.count)") }
  override func viewDidAppear(_ animated: Bool) { super.viewDidAppear(animated); mvsLog("appear"); let fix = ProcessInfo.processInfo.environment["MVS_FIX"] ?? ""; for s in [2.0, 5.0, 8.0, 12.0, 18.0, 26.0] { DispatchQueue.main.asyncAfter(deadline: .now() + s) { [weak self] in self?.mvsDiag(s) } }; if !fix.isEmpty { DispatchQueue.main.asyncAfter(deadline: .now() + 9.0) { [weak self] in self?.mvsFix(fix) } } }
  func mvsLog(_ s: String) { let line = "MVSLOG fix=\(ProcessInfo.processInfo.environment["MVS_FIX"] ?? "") " + s + "\n"; NSLog("%@", line); if let d = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first { let u = d.appendingPathComponent("mvs.log"); if let h = try? FileHandle(forWritingTo: u) { h.seekToEndOfFile(); h.write(line.data(using: .utf8)!); h.closeFile() } else { try? line.data(using: .utf8)!.write(to: u) } } }
  func mvsDiag(_ s: Double) { guard let wv = webView else { mvsLog("t=\(s) nowebview"); return }; mvsLog("tick \(s) loading=\(wv.isLoading) prog=\(String(format: "%.2f", wv.estimatedProgress))"); let base = "t=\(s) loading=\(wv.isLoading) prog=\(wv.estimatedProgress) url=\(wv.url?.absoluteString ?? "nil") frame=\(wv.frame) hidden=\(wv.isHidden) alpha=\(wv.alpha) opaque=\(wv.isOpaque) win=\(wv.window != nil)"; wv.evaluateJavaScript(MVS_DIAG_JS) { r, e in self.mvsLog(base + " js=\(String(describing: r)) err=\(String(describing: e))") } }
  func mvsFix(_ f: String) { guard let wv = webView else { return }; mvsLog("FIX " + f); if f == "resize" { let fr = wv.frame; wv.frame = fr.insetBy(dx: 0, dy: 20); DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { wv.frame = fr } } else if f == "reload" { wv.reload() } else if f == "load" { if let u = wv.url { wv.load(URLRequest(url: u)) } } }
}
